const b = $input.first().json.body || {};
const p = b.parameters || b || {};
const KEY = '<JWT_REDACTED>';
const rates = {solea:149, athena:139, marina:135, luna:129, aurora:119};
function pick(n){ n=(n||'').toLowerCase(); for (const k in rates){ if(n.indexOf(k)>=0) return {rate:rates[k],key:k}; } return {rate:129,key:'luna'}; }
const pr = pick(p.property);
const propName = 'Casa ' + pr.key.charAt(0).toUpperCase() + pr.key.slice(1);
function ymd(d){ return d.toISOString().slice(0,10); }
function addDays(s,n){ const d=new Date(s+'T12:00:00Z'); d.setUTCDate(d.getUTCDate()+n); return ymd(d); }
function isDate(s){ return typeof s==='string' && s.length===10 && s.charAt(4)==='-' && s.charAt(7)==='-'; }
const today = ymd(new Date());
let ci = isDate(p.check_in) ? p.check_in : today;
let nights = parseInt(p.nights);
let co = isDate(p.check_out) ? p.check_out : addDays(ci, (nights>0?nights:1));
nights = Math.max(1, Math.round((new Date(co)-new Date(ci))/86400000));
const cleaning=99; const total=pr.rate*nights+cleaning;
const guests = parseInt(p.guests)||2;
const guest_name = (p.guest_name || p.name || 'Guest');
const contact = (p.contact || p.email || p.phone || '');
const base='https://zkylrolpuwybsksspblj.supabase.co/rest/v1/casas_bookings';
const H = { apikey:KEY, Authorization:'Bearer '+KEY, 'Content-Type':'application/json' };
let rows=[];
try{ rows = await this.helpers.httpRequest({ method:'GET', url: base + '?property=eq.' + encodeURIComponent(propName) + '&status=neq.cancelled&check_in=lt.' + co + '&check_out=gt.' + ci + '&select=id', headers:H, json:true }); }catch(e){ rows=[]; }
if(Array.isArray(rows) && rows.length>0){ return [{ json:{ result: propName + ' just became unavailable for those dates. Shall I check other dates or another apartment?' } }]; }
const ref = 'CC-' + Math.random().toString(36).slice(2,7).toUpperCase();
try{ await this.helpers.httpRequest({ method:'POST', url: base, headers: Object.assign({ Prefer:'return=minimal' }, H), body: { ref, property:propName, check_in:ci, check_out:co, nights, guests, nightly_usd:pr.rate, total_usd:total, guest_name, contact, status:'held' }, json:true }); }catch(e){}
const link = 'https://andreytry.github.io/hotel-concierge-demo/book.html?ref=' + ref + '&p=' + encodeURIComponent(propName) + '&in=' + ci + '&out=' + co + '&g=' + guests + '&rate=' + pr.rate + '&total=' + total + '&name=' + encodeURIComponent(guest_name);
const result = 'All set! I have held ' + propName + ' for ' + guest_name + ', ' + ci + ' to ' + co + ', ' + nights + ' night' + (nights>1?'s':'') + ', total $' + total + '. Your reference is ' + ref + '. I have put your confirmation link in the chat - open it to confirm and pay: ' + link;
return [{ json: { result, link, ref } }];
